{
  "name": "wlan_tx_fill_desc",
  "confidence": "medium",
  "docstring": "Prepare the current WLAN TX frame descriptor and copy the selected 52-byte header template, updating DMA length and TX control fields before transmission.",
  "subsystem": "wlan",
  "var_renames": {
    "a1": "tx_ctx",
    "a2": "hdr_select",
    "a3": "frame_len",
    "v6": "hdr_src",
    "v7": "hdr_dst",
    "v9": "tx_param_raw",
    "v10": "tx_param_sel",
    "v11": "tx_frame_info"
  },
  "struct_hints": [
    {
      "offset": 28,
      "meaning": "tx_ctx: 64-bit pair holding the current TX frame-info pointer and associated TX descriptor pointer"
    },
    {
      "offset": 38,
      "meaning": "tx_ctx: TX status/sequence field cleared after descriptor preparation"
    },
    {
      "offset": 44,
      "meaning": "tx_frame_info: destination for the copied 52-byte header; also used as the header pointer stored in the descriptor"
    },
    {
      "offset": 48,
      "meaning": "tx_ctx: pending TX header length/status field cleared after descriptor preparation"
    },
    {
      "offset": 64,
      "meaning": "tx_frame_info: frame control flag word used to select the duplicated TX parameter byte"
    },
    {
      "offset": 80,
      "meaning": "tx_frame_info: prepared TX parameter/rate control field written from the global TX configuration"
    },
    {
      "offset": 24,
      "meaning": "tx_desc: DMA/base buffer address field used to compute the end address"
    },
    {
      "offset": 28,
      "meaning": "tx_desc: DMA end address, set to base+length-1 for short frames or base+4095 for the first buffer of a large frame"
    },
    {
      "offset": 32,
      "meaning": "tx_desc: DMA length/control field, frame_len+4 for short frames or scatter-list helper result+4 for large frames"
    },
    {
      "offset": 20,
      "meaning": "tx_desc: descriptor status field cleared for short frames"
    },
    {
      "offset": 40,
      "meaning": "tx_desc: additional descriptor status/reserved field cleared"
    },
    {
      "offset": 64,
      "meaning": "tx_desc: additional descriptor status/reserved field cleared"
    }
  ]
}
